INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (27, 2, 1, '2026-11-11', 13, 'Arrival on the Huangpu', 'Fly into PVG. Light walking day. Reach the Bund after dark if the flight allows.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (27, 1, 'The Bund', 'Shanghai', 5, 'Waterfront of colonial banks facing the Pudong skyline.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (28, 2, 2, '2026-11-12', 13, 'Pudong and the Bund', 'Skyline from Lujiazui by day, then walk the Bund in better light.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (28, 1, 'Lujiazui', 'Shanghai', 4, 'Pudong financial district and river viewpoint.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (28, 2, 'The Bund', 'Shanghai', 5, 'Daylight walk of the same waterfront, looking back at Pudong.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (29, 2, 3, '2026-11-13', 13, 'Concession streets and museum', 'Slow streets in the former French Concession, then Shanghai Museum East.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (29, 1, 'French Concession', 'Shanghai', 4, 'Plane-tree streets, lane houses, and cafes south of Huaihai Road.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (29, 2, 'Shanghai Museum East', 'Shanghai', 5, 'The city''s main collection of bronze, painting, and ceramics in Pudong.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (30, 2, 4, '2026-11-14', 13, 'Old city and West Bund', 'Yu Garden in the morning. West Bund river walk if energy remains. Last night in Shanghai.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (30, 1, 'Yu Garden', 'Shanghai', 4, 'Ming garden and old-city streets beside the City God Temple.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (30, 2, 'West Bund', 'Shanghai', 4, 'Huangpu industrial waterfront reused for galleries and walking.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (31, 2, 5, '2026-11-15', 14, 'Shanghai to Nantong', 'Hongqiao to Nantong West, then the Haohe moat. Reconfirm the train on 12306.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (31, 1, 'Haohe', 'Nantong', 4, 'City moat loop with gardens, museums, and walking paths.');
INSERT INTO day_train_rides (day_id, position, outgoing_city, destination_city, time_of_day, departure_time, arrival_time, duration_minutes) VALUES (31, 1, 'Shanghai', 'Nantong', 'afternoon', '15:09', '16:30', 81);
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (32, 2, 6, '2026-11-16', 14, 'Langshan and Tangzha', 'Wolf Hill in the morning. Tangzha industrial town in the afternoon.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (32, 1, 'Langshan', 'Nantong', 4, 'Temple hill at a bend of the Yangtze, south of the old city.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (32, 2, 'Nantong Museum', 'Nantong', 4, 'Zhang Jian''s museum garden on the Haohe, among the earliest in China.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (32, 3, 'Tangzha', 'Nantong', 4, 'Early mill town and industrial streets northwest of the center.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (33, 2, 7, '2026-11-17', 15, 'Nantong to Nanjing', 'Morning C-train into Nanjing. Presidential Palace and a first walk of the wall if time.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (33, 1, 'Presidential Palace', 'Nanjing', 4, 'Late-Qing and Republican compound in the city center.');
INSERT INTO day_train_rides (day_id, position, outgoing_city, destination_city, time_of_day, departure_time, arrival_time, duration_minutes) VALUES (33, 1, 'Nantong', 'Nanjing', 'morning', '09:58', '12:47', 169);
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (34, 2, 8, '2026-11-18', 15, 'Purple Mountain', 'Ming Xiaoling and Sun Yat-sen Mausoleum. Xuanwu Lake on the way back into the city.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (34, 1, 'Ming Xiaoling', 'Nanjing', 5, 'Tomb of the Hongwu emperor on the south slope of Purple Mountain.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (34, 2, 'Sun Yat-sen Mausoleum', 'Nanjing', 5, 'Memorial stairs and hall above the pine forest.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (34, 3, 'Xuanwu Lake', 'Nanjing', 4, 'City lake under the wall, between Purple Mountain and Xinjiekou.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (35, 2, 9, '2026-11-19', 15, 'Wall, museum, Fuzimiao', 'City wall in daylight. Nanjing Museum before it closes. Confucius Temple after dark.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (35, 1, 'Nanjing City Wall', 'Nanjing', 5, 'Ming brick wall; Zhonghua Gate or Taicheng are the usual walks.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (35, 2, 'Nanjing Museum', 'Nanjing', 5, 'Provincial museum east of the wall. Book a free timed ticket.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (35, 3, 'Fuzimiao', 'Nanjing', 4, 'Confucius Temple and Qinhuai River lantern streets.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (36, 2, 10, '2026-11-20', 16, 'Nanjing to Suzhou', 'Afternoon G-train. Humble Administrator''s Garden if you arrive with daylight, otherwise Pingjiang Road after dark.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (36, 1, 'Humble Administrator''s Garden', 'Suzhou', 5, 'Largest of the classical gardens, just north of the old city.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (36, 2, 'Pingjiang Road', 'Suzhou', 4, 'Canal street of white walls and stone bridges.');
INSERT INTO day_train_rides (day_id, position, outgoing_city, destination_city, time_of_day, departure_time, arrival_time, duration_minutes) VALUES (36, 1, 'Nanjing', 'Suzhou', 'afternoon', '14:22', '15:28', 66);
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (37, 2, 11, '2026-11-21', 16, 'Gardens and Suzhou Museum', 'Lingering Garden in the morning. I.M. Pei''s Suzhou Museum next door to the Humble Administrator''s Garden. Master of the Nets at dusk if the night opening is running.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (37, 1, 'Lingering Garden', 'Suzhou', 5, 'West-side garden known for borrowed views and scholar''s rocks.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (37, 2, 'Suzhou Museum', 'Suzhou', 5, 'I.M. Pei museum of jade, painting, and local craft beside the garden.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (37, 3, 'Master of the Nets Garden', 'Suzhou', 5, 'Smallest of the great gardens; compact courtyards off Shiquan Street.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (38, 2, 12, '2026-11-22', 16, 'Tiger Hill and Shantang', 'Tiger Hill in the morning. Shantang Street back toward the center. Last night in Suzhou.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (38, 1, 'Tiger Hill', 'Suzhou', 4, 'Leaning Yunyan Pagoda and quarry park northwest of the old city.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (38, 2, 'Shantang Street', 'Suzhou', 4, 'Canal street from Changmen out toward Tiger Hill.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (39, 2, 13, '2026-11-23', 17, 'Suzhou to Hangzhou', 'Afternoon train to Hangzhou East. West Lake for sunset if the light is clean.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (39, 1, 'West Lake', 'Hangzhou', 5, 'The lake that organizes the whole city. Walk, do not rush the circuit.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (39, 2, 'Broken Bridge', 'Hangzhou', 4, 'Bai Causeway entrance to the lake, looking toward the hills.');
INSERT INTO day_train_rides (day_id, position, outgoing_city, destination_city, time_of_day, departure_time, arrival_time, duration_minutes) VALUES (39, 1, 'Suzhou', 'Hangzhou', 'afternoon', '15:05', '16:43', 98);
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (40, 2, 14, '2026-11-24', 17, 'West Lake circuit', 'Su Causeway on foot or by bike. Leifeng Pagoda on the south shore.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (40, 1, 'Su Causeway', 'Hangzhou', 5, 'Six-bridge causeway across the lake, best in low autumn light.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (40, 2, 'Leifeng Pagoda', 'Hangzhou', 4, 'Rebuilt pagoda on the south shore with a view back over the lake.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (41, 2, 15, '2026-11-25', 17, 'Lingyin and Longjing', 'Lingyin Temple and Feilai Peak in the morning. Tea hills at Longjing in the afternoon. Pack for two nights on Huangshan.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (41, 1, 'Lingyin Temple', 'Hangzhou', 5, 'Large Chan temple in the hills west of the lake.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (41, 2, 'Feilai Peak', 'Hangzhou', 4, 'Cliff sculptures on the walk into Lingyin.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (41, 3, 'Longjing Village', 'Hangzhou', 4, 'Tea terraces above the lake. Walk, taste, do not buy a crate.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (42, 2, 16, '2026-11-26', 18, 'Hangzhou to Huangshan', 'Early train to Huangshan North, taxi to Tangkou, Yungu cable car up. Sunset from Refreshing Terrace or Beihai. First night on the mountain. Book park tickets, cable car, and a Beihai or Xihai bed before you go; November weather can close the upper trails.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (42, 1, 'Yungu Cableway', 'Huangshan', 4, 'East-side cable car onto the mountain, the usual ascent with luggage.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (42, 2, 'Beihai', 'Huangshan', 5, 'North summit plateau and the usual first-night base.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (42, 3, 'Refreshing Terrace', 'Huangshan', 5, 'Classic sunrise and sea-of-clouds terrace above Beihai.');
INSERT INTO day_train_rides (day_id, position, outgoing_city, destination_city, time_of_day, departure_time, arrival_time, duration_minutes) VALUES (42, 1, 'Hangzhou', 'Huangshan', 'morning', '08:07', '09:20', 73);
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (43, 2, 17, '2026-11-27', 18, 'Summit day', 'Sunrise, then West Sea Grand Canyon, Flying Rock, and Bright Summit. Second night on the mountain. Keep the descent for tomorrow so you are not hiking down in the dark.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (43, 1, 'West Sea Grand Canyon', 'Huangshan', 5, 'Stepped trail into the western cliffs. Allow half a day.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (43, 2, 'Flying Rock', 'Huangshan', 4, 'Balanced boulder on the ridge toward Bright Summit.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (43, 3, 'Bright Summit', 'Huangshan', 5, 'Open summit and a wide view in every direction.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (44, 2, 18, '2026-11-28', 19, 'Descend to Hongcun', 'Sunrise if the sky is clear, then down by Yungu or past Guest-Greeting Pine and Yuping. Taxi to Hongcun for the afternoon. Book the village ticket on the Yi County mini program.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (44, 1, 'Guest-Greeting Pine', 'Huangshan', 4, 'The pine at Yuping, on the western descent if you take that trail.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (44, 2, 'Hongcun', 'Hongcun', 5, 'Ming–Qing village laid out as a water ox, south of the mountain.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (45, 2, 19, '2026-11-29', 19, 'Xidi and Tunxi', 'Xidi in the morning. Tunxi Old Street in the afternoon if you prefer a city night before the train, otherwise stay in Hongcun.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (45, 1, 'Xidi', 'Hongcun', 5, 'Huizhou merchant village of memorial arches and carved halls.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (45, 2, 'Tunxi Old Street', 'Hongcun', 4, 'Stone shopping street in Huangshan city, useful as a last-night base by the station.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (46, 2, 20, '2026-11-30', 17, 'Return to Hangzhou', 'Huangshan North back to Hangzhou East. Qinghefang or a last West Lake walk. Buffer night before the flight.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (46, 1, 'Qinghefang', 'Hangzhou', 4, 'Old commercial street south of West Lake, close to the city hotels.');
INSERT INTO day_train_rides (day_id, position, outgoing_city, destination_city, time_of_day, departure_time, arrival_time, duration_minutes) VALUES (46, 1, 'Huangshan', 'Hangzhou', 'morning', '09:22', '10:55', 93);
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (47, 2, 21, '2026-12-01', 17, 'Departure', 'Fly out of Hangzhou Xiaoshan (HGH). Afternoon departure leaves a slow morning.', 1);
