INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (63, 6, 1, '2025-11-29', 31, 'Central Hong Kong', 'Trams along Des Voeux Road Central by day, then the Monster Building in Quarry Bay by evening.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (63, 1, 'Monster Building', 'Hong Kong', 4, 'Dense residential complex known for its striking appearance.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (63, 2, 'Des Voeux Road Central', 'Hong Kong', 4, 'Central Hong Kong thoroughfare and commercial corridor.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (64, 6, 2, '2025-11-30', 31, 'Ngong Ping and Victoria Peak', 'Ngong Ping 360 to the Tian Tan Buddha, then Victoria Peak for the evening skyline.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (64, 1, 'Tian Tan Buddha', 'Hong Kong', 5, 'Large seated Buddha statue on Lantau Island.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (64, 2, 'Victoria Peak', 'Hong Kong', 5, 'Famous viewpoint over the city.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (64, 3, 'Victoria Peak''s evening skyline', 'Hong Kong', 5, 'Night views over Hong Kong from Victoria Peak.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (65, 6, 3, '2025-12-01', 31, 'Cheung Chau to Guangzhou', 'Morning on Cheung Chau, then evening at Haixinsha Asian Games Park and Canton Tower.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (65, 1, 'Cheung Chau', 'Hong Kong', 5, 'Iconic harbor skyline and waterfront views.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (65, 2, 'Haixinsha Asian Games Park', 'Guangzhou', 4, 'Riverside park near the Pearl River.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (65, 3, 'Canton Tower', 'Guangzhou', 5, 'Tall observation tower and city landmark.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (66, 6, 4, '2025-12-02', 32, 'Shamian dao, museum, and hot springs', 'Shamian Dao and the Nanyue King Museum, then a night at Royal Hot Springs.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (66, 1, 'Shamian Dao', 'Guangzhou', 4, 'Historic island district with colonial-era architecture.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (66, 2, 'Nanyue King Museum', 'Guangzhou', 4, 'Museum focused on the Nanyue Kingdom history.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (66, 3, 'Royal Hot Springs', 'Zhuhai', 4, 'Hot spring resort and spa complex in Zhuhai.');
INSERT INTO days (id, trip_id, position, date, city_id, title, notes, visible) VALUES (67, 6, 5, '2025-12-03', 34, 'Historic and modern Macao', 'Monte Fortress, Ruins of St. Paul''s, and Senado Square, then Grand Lisboa, Lotus Garden, and The Parisian.', 1);
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (67, 1, 'Monte Fortress', 'Macao', 4, 'Historic fortress with city views.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (67, 2, 'Ruins of St. Paul''s', 'Macao', 5, 'Iconic church façade and heritage site.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (67, 3, 'Senado Square', 'Macao', 5, 'Historic public square in the center of Macao.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (67, 4, 'Garden of the Golden Chambers', 'Macao', 4, 'Historic garden and green space in Macao.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (67, 5, 'Grand Lisboa Hotel', 'Macao', 4, 'Major casino and hotel landmark.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (67, 6, 'Eiffel Tower at The Parisian Macao', 'Macao', 4, 'Replica landmark and viewing attraction.');
INSERT INTO day_attractions (day_id, position, name, city, rating, description) VALUES (67, 7, 'Lotus Garden', 'Macao', 4, 'Public garden and scenic stop.');
